export type Subscription = { "awaiting_billing_schedule"?: boolean; /** Format: int32. */ "billing_anchor_day"?: number; /** How often the subscription bills, frozen when the subscription was created. Read with billing_interval_count: monthly with a count of 3 bills quarterly. Omitted for subscriptions created before Flint recorded this interval. */ "billing_interval"?: "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Number of billing_interval units between charges, frozen when the subscription was created. Omitted for subscriptions created before Flint recorded this interval. Format: int32. */ "billing_interval_count"?: number; "billing_schedule_owner": "flint" | "external" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "billing_schedule_waiting_started_at"?: string; "cancel_at_period_end": boolean; /** RFC3339 timestamp. Format: date-time. */ "canceled_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "contract_end_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "contract_start_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "current_period_end"?: string; "current_period_start"?: string; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "customer_id": string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "line_items"?: Array<SubscriptionLineItem>; "merchant_id"?: string; "metadata"?: Record<string, string>; /** RFC3339 timestamp. Format: date-time. */ "next_billing_at"?: string; /** Recorded automatic payment retry time. Null when no retry time is available. Format: date-time. */ "next_retry_at"?: string | null; /** RFC3339 timestamp. Format: date-time. */ "paused_at"?: string; "payment_method"?: (({ "card"?: CardDetails; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "payment_method_id": string; "status": "pending" | "active" | "expired" | "removed" | "failed" | (string & {}); "type": "card" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "payment_method_id": string; "plan_id": string; /** What one billing period charges before tax and discounts, frozen when the subscription was created. Plan price changes after that do not change it. Omitted for subscriptions created before Flint recorded this amount. */ "recurring_amount_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "service_location"?: SubscriptionServiceLocation; /** RFC3339 timestamp. Format: date-time. */ "starts_at"?: string; "status": "trialing" | "active" | "paused" | "past_due" | "canceled" | "incomplete" | (string & {}); "subscription_id": string; "subscription_plan"?: (({ "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Format: int32. */ "billing_interval_count": number; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; "description"?: string; "line_items"?: Array<SubscriptionPlanLineItem>; "name": string; "plan_id": string; "setup_fee_money"?: MoneyValue; "status": "active" | "archived" | (string & {}); /** Format: int32. */ "trial_period_days"?: number; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "trial_end"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; };
